commits.content:
.time {
  font-size: 24px;
  font-weight: 700;
  background: #0b0051;
  text-align: center;
  width: 166px;
  padding: 10px;
  color: #ffffff;
}

.voltage-button {
  position: relative;

  button {
  color: #ffffff;
        font-weight: 700;
        background: #0D1127;
        background: linear-gradient(105deg, #b9adc5, #21063c, #25004b);
        padding: 14px 20px;
        border-radius: 5rem;
        font-size: 26px;
        line-height: 1em;
        letter-spacing: 0.075em;
        transition: background 0.3s;
        box-shadow: 5px 5px 10px #16003f;
    
  }

  /* Make the SVG glow visible all the time */
  svg {
    display: block;
    position: absolute;
    top: -0.75em;
    left: -0.25em;
    width: calc(100% + 0.5em);
    height: calc(100% + 1.5em);
    pointer-events: none;
    opacity: 1; /* Always visible */
    path {
      stroke-dasharray: 100;
      filter: url('#glow');
    }
    .line-1 {
      /* stroke: #f6de8d; */
      stroke-dashoffset: 0;
      animation: spark-1 13s linear infinite;
    }
    .line-2 {
      stroke: #1b004e;
      stroke-dashoffset: 100;
      animation: spark-2 10s linear infinite;
    }
  }

  
  .dots {
    opacity: 1;
    .dot {
      width: 1rem;
      height: 1rem;
      background: white;
      border-radius: 100%;
      position: absolute;
      opacity: 0;
    }
    .dot-1 {
      top: 0;
      left: 20%;
      animation: fly-up 3s linear infinite;
    }
    .dot-2 {
      top: 0;
      left: 55%;
      animation: fly-up 3s linear infinite;
      animation-delay: 0.5s;
    }
    .dot-3 {
      top: 0;
      left: 80%;
      animation: fly-up 3s linear infinite;
      animation-delay: 1s;
    }
    .dot-4 {
      bottom: 0;
      left: 30%;
      animation: fly-down 3s linear infinite;
      animation-delay: 2.5s;
    }
    .dot-5 {
      bottom: 0;
      left: 65%;
      animation: fly-down 3s linear infinite;
      animation-delay: 1.5s;
    }
  }
}

/* Animations remain the same */
@keyframes spark-1 {
  to {
    stroke-dashoffset: -1000;
  }
}
@keyframes spark-2 {
  to {
    stroke-dashoffset: -100;
  }
}
@keyframes fly-up {
  0% { opacity: 0; transform: translateY(0) scale(0.2); }
  5% { opacity: 1; transform: translateY(-1.5rem) scale(0.4); }
  10%, 100% { opacity: 0; transform: translateY(-3rem) scale(0.2); }
}
@keyframes fly-down {
  0% { opacity: 0; transform: translateY(0) scale(0.2); }
  5% { opacity: 1; transform: translateY(1.5rem) scale(0.4); }
  10%, 100% { opacity: 0; transform: translateY(3rem) scale(0.2); }
}
